{"implementation":"def solve(case):
    import math
    from fractions import Fraction

    if not isinstance(case, dict):
        raise TypeError("case must be an object")

    data = case.get("payload", case)
    if not isinstance(data, dict):
        raise TypeError("payload must be an object")
    if "segments" not in data:
        raise ValueError("missing required field: segments")
    if "budget" not in data:
        raise ValueError("missing required field: budget")

    segments = data["segments"]
    budget = data["budget"]
    if not isinstance(segments, list) or not segments:
        raise ValueError("segments must be a non-empty array")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise TypeError("budget must be an integer")
    if budget < 0:
        raise ValueError("budget must be non-negative")

    names = []
    importances = []
    minimums = []
    capacities = []
    seen_names = set()

    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise TypeError("each segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("segment %d is missing required field: %s" % (index, field))

        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str) or not name:
            raise ValueError("segment names must be non-empty strings")
        if name in seen_names:
            raise ValueError("segment names must be unique")
        if isinstance(importance, bool) or not isinstance(importance, (int, float)):
            raise TypeError("importance must be numeric")
        if isinstance(importance, float) and not math.isfinite(importance):
            raise ValueError("importance must be finite")
        if importance < 0:
            raise ValueError("importance must be non-negative")
        if isinstance(minimum, bool) or not isinstance(minimum, int):
            raise TypeError("minimum must be an integer")
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if minimum < 0:
            raise ValueError("minimum must be non-negative")
        if capacity < minimum:
            raise ValueError("capacity must be at least minimum")

        seen_names.add(name)
        names.append(name)
        importances.append(Fraction(importance))
        minimums.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(minimums)
    capacity_total = sum(capacities)
    if budget < minimum_total:
        raise ValueError("budget is below the minimum quota sum")
    if budget > capacity_total:
        raise ValueError("budget exceeds total capacity")

    allocations = list(minimums)
    remaining = budget - minimum_total
    while remaining:
        eligible = (i for i in range(len(segments)) if allocations[i] < capacities[i])
        selected = max(eligible, key=lambda i: importances[i] / (allocations[i] + 1))
        allocations[selected] += 1
        remaining -= 1

    by_name = {name: allocations[i] for i, name in enumerate(names)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}
